def init_agent():
    return {'known': jnp.full((9,), -1, jnp.int32),
            'partner_seen': jnp.zeros((9,), jnp.bool_),
            'positions': jnp.zeros((9, 2), jnp.int32),
            'behavior_log': jnp.zeros((280,), jnp.float32)}


def beliefs(obs, known, behavior_log):
    assignments = jnp.asarray(ASSIGNMENTS, jnp.int32)
    valid = jnp.all((known[None, :] < 0) | (assignments == known[None, :]), axis=1)
    hints = obs.node_features[9:13, 3:6].astype(jnp.float32)
    linked = obs.adjacency_matrix[9:13, :9].astype(jnp.float32)
    # Hints are evidence of literal membership, with room for an erroneous placement.
    card_hint = linked.T @ hints
    has_hint = jnp.sum(linked, axis=0) > 0
    matches = jnp.take_along_axis(card_hint[None, :, :], assignments[:, :, None], axis=2)[:, :, 0]
    likelihood = jnp.prod(jnp.where(has_hint[None, :], jnp.where(matches > 0, 1., .025), 1.), axis=1)
    labeled_log = behavior_log[jnp.asarray(PARTITION_INDEX, jnp.int32)]
    behavior = jnp.exp(labeled_log - jnp.max(labeled_log))
    weight = valid.astype(jnp.float32) * likelihood * behavior
    weight /= jnp.maximum(jnp.sum(weight), 1e-20)
    colors = jnp.einsum('s,sic->ic', weight, jax.nn.one_hot(assignments, 3))
    pairs = jnp.asarray(PAIRS)
    triples = jnp.asarray(TRIPLES)
    pair_prob = weight @ (assignments[:, pairs[:, 0]] == assignments[:, pairs[:, 1]]).astype(jnp.float32)
    triple_same = ((assignments[:, triples[:, 0]] == assignments[:, triples[:, 1]]) &
                   (assignments[:, triples[:, 0]] == assignments[:, triples[:, 2]]))
    triple_prob = weight @ triple_same.astype(jnp.float32)
    return weight, colors, pair_prob, triple_prob, triple_same


def geometry(positions):
    pairs = jnp.asarray(PAIRS)
    triples = jnp.asarray(TRIPLES)
    distances = jnp.sum(jnp.abs(positions[..., :, None, :] - positions[..., None, :, :]), axis=-1)
    pair_dist = distances[..., pairs[:, 0], pairs[:, 1]]
    d0 = distances[..., triples[:, 0], triples[:, 1]]
    d1 = distances[..., triples[:, 0], triples[:, 2]]
    d2 = distances[..., triples[:, 1], triples[:, 2]]
    connected = ((d0 == 1).astype(jnp.int32) + (d1 == 1) + (d2 == 1)) >= 2
    mst = d0 + d1 + d2 - jnp.maximum(d0, jnp.maximum(d1, d2))
    return pair_dist, connected, mst


def layout_value(positions, pair_prob, triple_prob):
    pair_dist, connected, mst = geometry(positions)
    return (4. * ((pair_dist == 1) @ pair_prob)
            + 2. * (connected @ triple_prob)
            - .25 * (mst @ triple_prob)
            - .008 * jnp.sum(pair_dist, axis=-1))



def move_boards(pos):
    ids = jnp.arange(729)
    cards = ids // 81
    cells = ids % 81
    destinations = jnp.stack((cells // 9, cells % 9), axis=-1)
    boards = jnp.broadcast_to(pos, (729, 9, 2))
    return boards.at[ids, cards].set(destinations)


def public_move_mask(pos, locked):
    nodes = jnp.arange(9)
    keep = nodes[None, :] != nodes[:, None]
    distance = jnp.sum(jnp.abs(pos[:, None, :] - pos[None, :, :]), axis=-1)
    reach = (distance[None, :, :] <= 1) & keep[:, :, None] & keep[:, None, :]
    def connect(k, reach):
        return reach | (reach[:, :, k, None] & reach[:, None, k, :])
    reach = jax.lax.fori_loop(0, 9, connect, reach)
    cells = jnp.stack((jnp.arange(81) // 9, jnp.arange(81) % 9), axis=1)
    dest_dist = jnp.sum(jnp.abs(cells[:, None, :] - pos[None, :, :]), axis=-1)
    connects = jnp.einsum('ijk,dk->idj', reach.astype(jnp.int32), (dest_dist == 1).astype(jnp.int32)) > 0
    connected = jnp.all(connects | ~keep[:, None, :], axis=-1)
    empty = jnp.all(dest_dist != 0, axis=1)
    return (connected & empty[None, :] & ~locked[:, None]).reshape(729)


def informative_observation(obs, weight, color_prob, entropy, move_mask, partner_seen):
    assignments = jnp.asarray(ASSIGNMENTS, jnp.int32)
    pairs = jnp.asarray(PAIRS)
    triples = jnp.asarray(TRIPLES)
    pair_same = assignments[:, pairs[:, 0]] == assignments[:, pairs[:, 1]]
    triple_same = ((assignments[:, triples[:, 0]] == assignments[:, triples[:, 1]]) &
                   (assignments[:, triples[:, 0]] == assignments[:, triples[:, 2]]))
    hidden_features = jnp.concatenate((pair_same, triple_same), axis=1).astype(jnp.float32)
    observation_joint = (weight[:, None, None] * jax.nn.one_hot(assignments, 3)).reshape(1680, 27)
    conditional_features = observation_joint.T @ hidden_features
    # A connected nine-card board has at most 20 exposed sides, hence
    # at most 20 empty destinations and 180 candidate card/destination pairs.
    legal_ids = jnp.nonzero(move_mask, size=180, fill_value=0)[0]
    selected_mask = move_mask[legal_ids]
    pair_dist, complete, mst = geometry(move_boards(obs.positions)[legal_ids])
    move_features = jnp.concatenate((4. * (pair_dist == 1), 2. * complete - .25 * mst), axis=1)
    conditional_utility = move_features @ conditional_features.T
    conditional_utility -= .008 * jnp.sum(pair_dist, axis=1)[:, None] * color_prob.reshape(1, 27)
    expected_best = jnp.sum(jnp.max(jnp.where(selected_mask[:, None], conditional_utility, -1e9), axis=0).reshape(9, 3), axis=1)
    values = expected_best + .15 * entropy + .001 * partner_seen
    def first_observation(_):
        one_hot = jax.nn.one_hot(assignments, 3)
        compact_cost = .008 * jnp.sum(pair_dist, axis=1)
        def evaluate(i, pair_values):
            joint = (observation_joint[:, None, :] * one_hot[:, i, :, None]).reshape(1680, 81)
            joint_features = joint.T @ hidden_features
            joint_prob = jnp.sum(joint, axis=0)
            utilities = move_features @ joint_features.T - compact_cost[:, None] * joint_prob[None, :]
            best = jnp.max(jnp.where(selected_mask[:, None], utilities, -1e9), axis=0).reshape(3, 9, 3)
            joint_prob = joint_prob.reshape(3, 9, 3)
            first_prob = jnp.sum(joint_prob, axis=-1, keepdims=True)
            cond_prob = joint_prob / jnp.maximum(first_prob, 1e-10)
            weighted_entropy = -jnp.sum(joint_prob * jnp.log(jnp.maximum(cond_prob, 1e-10)), axis=-1)
            second_values = jnp.sum(best, axis=-1) + .15 * weighted_entropy
            second_legal = obs.legal_actions[1:10] & (jnp.arange(9) != i)
            value = jnp.sum(jnp.max(jnp.where(second_legal[None, :], second_values, -1e9), axis=1))
            return pair_values.at[i].set(value + .15 * entropy[i] + .001 * partner_seen[i])
        return jax.lax.fori_loop(0, 9, evaluate, jnp.zeros((9,), jnp.float32))
    values = jax.lax.cond(obs.node_features[0, 11] == 0, first_observation, lambda _: values, operand=None)
    return 1 + jnp.argmax(jnp.where(obs.legal_actions[1:10], values, -1e9))

def agent_act(obs, reset, memory, rng):
    memory = jax.tree.map(lambda x, z: jnp.where(reset, z, x), memory, init_agent())
    feat = obs.node_features
    visible = jnp.sum(feat[:9, :3], axis=1) > 0
    known = jnp.where(visible, jnp.argmax(feat[:9, :3], axis=1).astype(jnp.int32), memory['known'])
    partner_seen = memory['partner_seen'] | (feat[:9, 9] > 0)
    pairs = jnp.asarray(PAIRS)
    old_dist = jnp.sum(jnp.abs(memory['positions'][pairs[:, 0]] - memory['positions'][pairs[:, 1]]), axis=1)
    new_dist = jnp.sum(jnp.abs(obs.positions[pairs[:, 0]] - obs.positions[pairs[:, 1]]), axis=1)
    assignments = jnp.asarray(PARTITIONS, jnp.int32)
    seen_count = jnp.sum(jax.nn.one_hot(assignments, 3) * partner_seen[None, :, None], axis=1)
    remaining = 3. - seen_count
    unseen_n = 9. - jnp.sum(partner_seen)
    unseen_colors = remaining / jnp.maximum(unseen_n, 1.)
    a, b = pairs[:, 0], pairs[:, 1]
    pa = jnp.take_along_axis(unseen_colors, assignments[:, a], axis=1)
    pb = jnp.take_along_axis(unseen_colors, assignments[:, b], axis=1)
    both_unknown = jnp.sum(remaining * (remaining - 1.), axis=1) / jnp.maximum(unseen_n * (unseen_n - 1.), 1.)
    partner_pair = jnp.where(partner_seen[None, a],
        jnp.where(partner_seen[None, b], assignments[:, a] == assignments[:, b], pa),
        jnp.where(partner_seen[None, b], pb, both_unknown[:, None]))
    old_mask = public_move_mask(memory['positions'], feat[:9, 8] > 0)
    alternative_ids = jnp.nonzero(old_mask, size=180, fill_value=0)[0]
    alternative_boards = move_boards(memory['positions'])[alternative_ids]
    alternative_dist = jnp.sum(jnp.abs(alternative_boards[:, a, :] - alternative_boards[:, b, :]), axis=-1)
    alternative_features = (alternative_dist == 1).astype(jnp.float32) - .05 * alternative_dist
    chosen_features = (new_dist == 1).astype(jnp.float32) - .05 * new_dist
    alternative_valid = old_mask[alternative_ids]
    known_pair = ((assignments[:, a] == assignments[:, b]) & partner_seen[None, a] & partner_seen[None, b]).astype(jnp.float32)
    def regret(pair_belief):
        def update(k, best):
            features = jax.lax.dynamic_slice(alternative_features, (k * 20, 0), (20, 36))
            valid_actions = jax.lax.dynamic_slice(alternative_valid, (k * 20,), (20,))
            options = features @ pair_belief.T
            return jnp.maximum(best, jnp.max(jnp.where(valid_actions[:, None], options, -1e9), axis=0))
        best = jax.lax.fori_loop(0, 9, update, jnp.full((280,), -1e9, jnp.float32))
        chosen = pair_belief @ chosen_features
        return jnp.maximum(best - chosen, 0.)
    count_regret = regret(partner_pair)
    observed_regret = regret(known_pair)
    increment = jnp.log(.2 + .5 * jnp.exp(-2.5 * count_regret) + .3 * jnp.exp(-2.5 * observed_regret))
    partner_moved = (feat[0, 10] == 0) & (feat[0, 11] == 3) & jnp.any(obs.positions != memory['positions'])
    behavior_log = memory['behavior_log'] + jnp.where(partner_moved, increment, 0.)
    behavior_log -= jnp.max(behavior_log)
    weight, color_prob, pair_prob, triple_prob, triple_same = beliefs(obs, known, behavior_log)
    pos = obs.positions
    _, connected, _ = geometry(pos)
    solved_each = triple_same.astype(jnp.int32) @ connected.astype(jnp.int32) == 3
    solved_prob = jnp.sum(weight * solved_each)
    entropy = -jnp.sum(color_prob * jnp.log(jnp.maximum(color_prob, 1e-10)), axis=1)
    move_mask = public_move_mask(pos, feat[:9, 8] > 0)
    def observe_action(_):
        return informative_observation(obs, weight, color_prob, entropy, move_mask, partner_seen)

    def move_action(_):
        move_ids = jnp.arange(729)
        cards = move_ids // 81
        cells = move_ids % 81
        destinations = jnp.stack((cells // 9, cells % 9), axis=-1)
        boards = jnp.broadcast_to(pos, (729, 9, 2))
        boards = boards.at[move_ids, cards].set(destinations)
        values = layout_value(boards, pair_prob, triple_prob)
        # Stable, small displacement breaks ties without imposing a color layout.
        values -= .001 * jnp.sum(jnp.abs(destinations - pos[cards]), axis=1)
        masked_values = jnp.where(obs.legal_actions[10:739], values, -1e9)
        greedy = jnp.argmax(masked_values)
        current_pair_dist, _, _ = geometry(boards[greedy])
        greedy_edges = (current_pair_dist == 1) @ pair_prob
        operations = jnp.sum(jnp.any(feat[9:13, 3:6] > 0, axis=1)) + jnp.sum(feat[9:13, 8] > 0)
        can_repair = (operations == 6) & (jnp.min(jnp.max(color_prob, axis=1)) > .999) & (greedy_edges < 5.995)
        def repair(_):
            _, beam = jax.lax.top_k(masked_values, 16)
            def evaluate(k, scores):
                board = boards[beam[k]]
                child_mask = public_move_mask(board, feat[:9, 8] > 0)
                child_ids = jnp.nonzero(child_mask, size=180, fill_value=0)[0]
                child_boards = move_boards(board)[child_ids]
                child_dist, child_complete, _ = geometry(child_boards)
                child_edges = (child_dist == 1) @ pair_prob
                wins = child_mask[child_ids] & (child_edges > 5.995) & ((child_complete @ triple_prob) > 2.995)
                # Among setups with a one-move finish, preserve the most immediate progress.
                value = jnp.where(jnp.any(wins), masked_values[beam[k]], -1e9)
                return scores.at[k].set(value)
            scores = jax.lax.fori_loop(0, 16, evaluate, jnp.full((16,), -1e9, jnp.float32))
            return jnp.where(jnp.max(scores) > -1e8, beam[jnp.argmax(scores)], greedy)
        chosen = jax.lax.cond(can_repair, repair, lambda _: greedy, operand=None)
        return 10 + chosen

    def hint_action(_):
        hints = feat[9:13, 3:6].astype(jnp.float32)
        correct = hints @ color_prob.T
        # Prefer an immovable anchor already connected to its own color group.
        pairs = jnp.asarray(PAIRS)
        pair_matrix = jnp.zeros((9, 9), jnp.float32)
        pair_matrix = pair_matrix.at[pairs[:, 0], pairs[:, 1]].set(pair_prob)
        pair_matrix = pair_matrix + pair_matrix.T
        adjacent = (obs.adjacency_matrix[:9, :9] > 0) & ~jnp.eye(9, dtype=jnp.bool_)
        links = jnp.sum(pair_matrix * adjacent, axis=1)
        safe = jnp.sum(triple_same.astype(jnp.float32) * weight[:, None], axis=0)
        triples = jnp.asarray(TRIPLES)
        complete_card = jnp.sum(jax.nn.one_hot(triples, 9), axis=1).T @ (safe * connected)
        information = -jnp.sum(jnp.where(hints > 0, 1., 0.), axis=1)
        placement_value = (5. * correct + 1.5 * complete_card[None, :] + .35 * links[None, :]
                           + .1 * information[:, None])
        singleton = jnp.sum(hints, axis=1) == 1
        early_safe = (correct > .98) & jnp.where(singleton[:, None], jnp.ones((1, 9), jnp.bool_), complete_card[None, :] > .98)
        placement_value += 22. * early_safe
        placement_value += (1.2 * singleton[:, None] + .3) * (~partner_seen[None, :]) * correct
        actions = 743 + jnp.arange(4)[:, None] * 81 + pos[None, :, 0] * 9 + pos[None, :, 1]
        values = jnp.full((1068,), -1e9)
        values = values.at[actions.reshape(-1)].set(placement_value.reshape(-1))
        # Revealing avoids a premature lock and retains a higher terminal score.
        values = values.at[739:743].set(jnp.asarray([20., 19.9, 19.8, 19.7]))
        return jnp.argmax(jnp.where(obs.legal_actions, values, -1e9))

    phase = feat[0, 11].astype(jnp.int32)
    hint_operations = jnp.sum(jnp.any(feat[9:13, 3:6] > 0, axis=1)) + jnp.sum(feat[9:13, 8] > 0)
    stop_threshold = jnp.where(hint_operations < 5, .65, .45)
    action = jax.lax.switch(phase, (
        lambda _: jnp.where(solved_prob > stop_threshold, 1067, observe_action(None)),
        observe_action,
        move_action,
        hint_action), operand=None).astype(jnp.int32)
    action = jnp.where(feat[0, 10] > 0, action, 0).astype(jnp.int32)
    action = jnp.where(obs.legal_actions[action], action, jnp.argmax(obs.legal_actions)).astype(jnp.int32)
    next_memory = {'known': known, 'partner_seen': partner_seen, 'positions': pos, 'behavior_log': behavior_log}
    return action, next_memory, {'known': known, 'color_prob': color_prob, 'solved_prob': solved_prob,
                               'hint_sets': feat[9:13, 3:6], 'legal_move_count': jnp.sum(move_mask),
                               'legal_mismatch': jnp.where((phase == 2) & (feat[0, 10] > 0), jnp.sum(move_mask != obs.legal_actions[10:739]), 0)}
